"use client";
import { ArtemisScope } from "./artemis-scope";
import type { ArtemisTestimonialsContent } from "./components/testimonials/content";
import View3 from "./components/testimonials/variants/04-archive";
const variants={"archive":View3};
export type { ArtemisTestimonialsContent, ArtemisTestimonialsImage, ArtemisTestimonialsQuote } from "./components/testimonials/content";
export interface ArtemisTestimonialsProps { className?: string; variant?: "archive"; /** The words on the testimonials; anything left out keeps the layout's own copy. */ content?: Partial<ArtemisTestimonialsContent>; }
export function ArtemisTestimonials({className,variant="archive",content}:ArtemisTestimonialsProps) {const View=variants[variant];return <ArtemisScope className={className}><div className="art:flex art:w-full art:min-w-0 art:flex-col art:items-center"><View content={content}/></div></ArtemisScope>;}

// @zeus-internal

/** A picture, and the words that describe it. */
export interface ArtemisTestimonialsImage {
  src: string;
  /** What the picture shows; empty for a purely decorative one. */
  alt: string;
}

/** One testimonial: what was said, and who said it. */
export interface ArtemisTestimonialsQuote {
  /** What they said, without quotation marks; marquee, spotlight, grid and vertical add their own. All layouts. */
  quote: string;
  /** Who said it. All layouts. */
  name: string;
  /** Their title and company as one line, such as "Frontend Lead, Workspace". All layouts. */
  role: string;
  /** Their photo. marquee, spotlight, grid and archive, which show the person's initials in its place when you leave it out. */
  avatar?: ArtemisTestimonialsImage;
  /** A short result over the quote, such as "18 days saved". vertical. */
  metric?: string;
}

/** The words on an Artemis testimonials section. Every layout reads this shape, so you can switch layouts and keep them. */
export interface ArtemisTestimonialsContent {
  /** The short label over the heading; over the quote in spotlight. All layouts. */
  badge: string;
  /** The heading. marquee, grid, archive and vertical. */
  headline?: string;
  /** The heading's second part. marquee and grid reveal it after `headline`, archive starts a new line for it, and vertical runs it on after `headline`. Left out, it keeps the layout's own only when `headline` is left out too. */
  headlineAccent?: string;
  /** A sentence beside or under the heading. marquee, grid and archive. */
  subhead?: string;
  /**
   * The testimonials. All layouts. marquee scrolls them in two rows, the first half on top, and eight or more look
   * best; spotlight shows one at a time with a photo button for each, and four look best; grid shows the first one
   * larger; archive pins them in up to three columns; vertical fills three scrolling columns in order, shows the third
   * from 1024px wide, and nine look best.
   */
  quotes: ArtemisTestimonialsQuote[];
  /** The word after the number of quotes, as in "9 dispatches". vertical. */
  countLabel?: string;
  /** A short line beside that count. vertical. */
  note?: string;
}

"use client";
// @zeus-internal
import { motion, useReducedMotion } from "motion/react";
import { ARTEMIS_EASE_OUT } from "../../../lib/ease";
import type { ArtemisTestimonialsContent } from "../content";
const DEFAULT = {
    badge: "Hall of fame",
    headline: "Builders who never",
    headlineAccent: "ship alone.",
    subhead: "Field notes from teams shipping with Artemis.",
    quotes: [
        { quote: "Shipped our pricing page in an afternoon. The motion is the part I could never get right by hand — now it just feels native.", name: "Morgan Wells", role: "Frontend Lead @ Workspace", avatar: { src: "/assets/artemis/83b960a1aaa67c851088.svg", alt: "" } },
        { quote: "The agent primitives saved us weeks. Streaming, tool calls, thinking states — all handled, all ours to edit.", name: "Cameron Avery", role: "Design Engineer @ Group B", avatar: { src: "/assets/artemis/83b960a1aaa67c851088.svg", alt: "" } },
        { quote: "Every block reads perfectly in light and dark. We haven't filed a single theme bug since we switched.", name: "Robin Ellis", role: "Product Designer @ Group F", avatar: { src: "/assets/artemis/83b960a1aaa67c851088.svg", alt: "" } },
        { quote: "Copy-paste source means no black-box dependency. We read every line, own every line, and ship with confidence.", name: "Jordan Stone", role: "Staff Engineer @ Group C", avatar: { src: "/assets/artemis/327d06eee6b741023403.svg", alt: "" } },
        { quote: "Installed from our private registry in one command. Onboarding new engineers is trivial now.", name: "Liam O'Brien", role: "CTO @ Group E", avatar: { src: "/assets/artemis/327d06eee6b741023403.svg", alt: "" } },
        { quote: "Feels like the components were designed by someone who actually ships products, not just demos.", name: "Avery Stone", role: "Founder @ Group A", avatar: { src: "/assets/artemis/83b960a1aaa67c851088.svg", alt: "" } },
    ],
} satisfies ArtemisTestimonialsContent;
/** Each card's tilt, the label under its photo and its file number, by position. They only decorate, and repeat after six. */
const TILTS = [-1.2, 0.8, -0.6, 1.1, -0.9, 0.6];
const FIGURES = ["FIG. A", "FIG. M", "FIG. S", "FIG. E", "FIG. D", "FIG. R"];
const REFS = ["ARC-8492", "ARC-3391", "ARC-7721", "ARC-9102", "ARC-2104", "ARC-5567"];
/** Up to two initials from a name, shown in place of a missing photo. */
const initials = (name: string) => name.split(/\s+/).filter(Boolean).slice(0, 2).map((part) => part[0]?.toUpperCase() ?? "").join("");
export default function TestimonialsArchive({ content }: { content?: Partial<ArtemisTestimonialsContent> } = {}) {
    const copy = { ...DEFAULT, ...content };
    const accent = content?.headline === undefined ? copy.headlineAccent : content.headlineAccent;
    const reduce = useReducedMotion();
    return (<>
      <div className="art:w-full">
        <section className="art:w-full art:px-2">
          <div className="art:mx-auto art:w-full art:max-w-6xl">
            <div className="art:flex art:flex-col art:gap-4 art:@min-[640px]/artemis:flex-row art:@min-[640px]/artemis:items-end art:@min-[640px]/artemis:justify-between">
              <div>
                <span className="art:inline-flex art:items-center art:gap-2 art:rounded-md art:border art:border-border/60 art:bg-background art:px-2.5 art:py-1 art:font-mono art:text-xs art:text-muted-foreground art:uppercase art:tracking-[0.18em]">
                  {copy.badge}
                </span>
                <h2 className="art:mt-5 art:text-balance art:font-sans art:text-foreground art:leading-[1.05] art:text-4xl art:font-medium">
                  <span className="art:block">
                    {copy.headline}
                  </span>
                  {accent ? (<span className="art:block">
                      {accent}
                    </span>) : null}
                </h2>
              </div>
              <p className="art:font-mono art:text-muted-foreground art:text-sm art:tracking-tight art:@min-[640px]/artemis:pb-2">
                {copy.subhead}
              </p>
            </div>
            <div className="art:mt-20 art:grid art:grid-cols-1 art:items-start art:gap-x-6 art:gap-y-14 art:@min-[640px]/artemis:grid-cols-2 art:@min-[1024px]/artemis:grid-cols-3">
              {copy.quotes.map((item, index) => {
            const tilt = TILTS[index % TILTS.length];
            return (<motion.figure key={index} className="art:relative art:rounded art:border art:border-border/70 art:bg-muted/40 art:p-5" initial={{ opacity: 0, y: 24, rotate: tilt }} animate={{ rotate: tilt }} whileInView={{ opacity: 1, y: 0 }} viewport={{ once: true, margin: "-40px" }} transition={reduce ? { duration: 0 } : { duration: 0.5, ease: ARTEMIS_EASE_OUT, delay: index * 0.06 }}>
                <div className="art:-top-9 art:absolute art:right-3 art:w-[5.5rem] art:rotate-[5deg]">
                  <div className="art:rounded-sm art:border art:border-border/60 art:bg-background art:p-1.5">
                    {item.avatar ? (<img src={item.avatar.src} alt={item.avatar.alt} aria-hidden="true" width="72" height="72" loading="lazy" className="art:aspect-square art:w-full art:rounded-sm art:bg-muted art:object-cover"/>) : (<span aria-hidden="true" className="art:grid art:aspect-square art:w-full art:place-items-center art:rounded-sm art:bg-muted art:font-sans art:text-lg art:text-muted-foreground art:italic">
                        {initials(item.name)}
                      </span>)}
                    <p className="art:mt-1 art:text-center art:font-sans art:text-xs art:text-muted-foreground art:italic">
                      {FIGURES[index % FIGURES.length]}
                    </p>
                  </div>
                </div>
                <p className="art:pr-24 art:font-mono art:text-xs art:text-muted-foreground art:tracking-[0.2em]">
                  {"REF "}
                  <span className="art:ml-1 art:text-foreground">
                    {REFS[index % REFS.length]}
                  </span>
                </p>
                <blockquote className="art:mt-7 art:max-w-[15rem] art:font-mono art:text-foreground art:text-sm art:leading-6">
                  {item.quote}
                </blockquote>
                <figcaption className="art:mt-5 art:flex art:items-end art:justify-between art:border-border/70 art:border-t art:border-dashed art:pt-3">
                  <div>
                    <p className="art:font-sans art:text-base art:text-foreground art:italic">
                      {item.name}
                    </p>
                    <p className="art:mt-0.5 art:font-mono art:text-xs art:text-muted-foreground art:uppercase art:tracking-[0.12em]">
                      {item.role}
                    </p>
                  </div>
                  <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="art:lucide art:lucide-mail art:size-3.5 art:text-muted-foreground/40" aria-hidden="true">
                    <path d="m22 7-8.991 5.727a2 2 0 0 1-2.009 0L2 7"/>
                    <rect x="2" y="4" width="20" height="16" rx="2"/>
                  </svg>
                </figcaption>
              </motion.figure>);
        })}
            </div>
          </div>
        </section>
      </div>
    </>);
}
